        ticks_positive_or_zero("audio.duck.release", duck.release)?;
        ticks_positive_or_zero("audio.duck.pre_roll", duck.pre_roll)?;
        ticks_positive_or_zero("audio.duck.hold", duck.hold)?;
    }
