    in_range("audio.noise_reduction", props.noise_reduction, 0.0, 1.0)?;
    in_range("audio.isolation", props.isolation, 0.0, 1.0)?;
    if let Some(compressor) = &props.compressor {
        check_compressor("audio.compressor", compressor)?;
    }
